// ===== 数据源覆盖: 若数据管理页保存过数据(localStorage), 优先使用 =====
(function () {
    var SKEY = 'loupan_units_v1';
    try {
        var saved = localStorage.getItem(SKEY);
        if (saved) {
            var parsed = JSON.parse(saved);
            if (Array.isArray(parsed) && parsed.length > 0) {
                window.UNITS = parsed;
                console.log('[units] 使用数据管理页保存的数据 (' + parsed.length + ' 条)');
            }
        }
    } catch (e) { /* localStorage 不可用时回退默认数据 */ }
})();
